// ServerInterface represents all server handlers.
type ServerInterface interface {
	// Report process liveness.
	// (GET /healthz)
	GetHealth(w http.ResponseWriter, r *http.Request)
	// Report process liveness without a response body.
	// (HEAD /healthz)
	HeadHealth(w http.ResponseWriter, r *http.Request)
	// Report process-local Prometheus metrics.
	// (GET /metrics)
	GetMetrics(w http.ResponseWriter, r *http.Request)
	// Report service readiness.
	// (GET /readyz)
	GetReadiness(w http.ResponseWriter, r *http.Request)
	// Report service readiness without a response body.
	// (HEAD /readyz)
	HeadReadiness(w http.ResponseWriter, r *http.Request)
	// Process one inbound DKIM2 message.
	// (POST /v1/process)
	ProcessMessage(w http.ResponseWriter, r *http.Request)
	// Revise one ordinary-transit DKIM2 message.
	// (POST /v1/revise)
	ReviseMessage(w http.ResponseWriter, r *http.Request)
	// Sign one originator DKIM2 message.
	// (POST /v1/sign)
	SignMessage(w http.ResponseWriter, r *http.Request)
}

